from collections import Counter
def transform(grid):
    R,C=len(grid),len(grid[0])
    def lines(get,n):
        idx=[];col=[]
        for i in range(n):
            cnt=Counter(get(i)); cc,m=cnt.most_common(1)[0]
            if m>0.6*n: idx.append(i); col.append(cc)
        return idx,col
    hr,hc=lines(lambda r:grid[r],R)
    vr,vc=lines(lambda c:[grid[r][c] for r in range(R)],C)
    rc={r:c for r,c in zip(hr,hc)}; cc2={c:c for c in vr}
    cc2={c:v for c,v in zip(vr,vc)}
    def marked(r,c):
        v=grid[r][c]
        return r in rc and c in cc2 and v!=rc[r] and v!=cc2[c]
    hl=[r for r in hr if any(marked(r,c) for c in range(C))]
    vl=[c for c in vr if any(marked(r,c) for r in range(R))]
    I=[[grid[r][c] for c in vl] for r in hl]
    out=[]
    for i in range(len(hl)-1):
        row=[]
        for j in range(len(vl)-1):
            corners={I[i][j],I[i][j+1],I[i+1][j],I[i+1][j+1]}
            row.append(corners.pop() if len(corners)==1 else 9)
        out.append(row)
    return out
